tool_input.command:
cd data/dossiers; wc -c 2026-10-31-*; for f in 2026-10-31-*; do node -e "
const d=JSON.parse(require('fs').readFileSync('$f','utf8'));
const {sources,...r}=d;console.log(JSON.stringify(r));
for(const s of sources)console.log(s.outlet,'|',s.access,'|',s.method,'|',s.wire,'|',(s.text||'').length,'|',s.title||s.headline)"; done

cat > /tmp/sum.js <<'EOF'
const fs=require('fs');
for(const f of process.argv.slice(2)){
const d=JSON.parse(fs.readFileSync(f,'utf8'));
const {sources,...r}=d;console.log('\n##',f,JSON.stringify(r));
for(const s of sources)console.log(' -',s.outlet,'|',s.access,'|',s.method,'|',s.wire,'|',(s.text||'').length,'|',s.title||s.headline);}
EOF
node /tmp/sum.js data/dossiers/2026-10-31-*.json
